// The rich text editor's toolbar glyphs, from the timeless-gowtham
// branch's playground/v2/assets/rte/*.svg — the Figma file's own icons,
// inlined so the component needs no assets.
import * as React from "react"

function icon(viewBox: string, children: React.ReactNode) {
  return function RteIcon(props: React.SVGProps<SVGSVGElement>) {
    return (
      <svg viewBox={viewBox} fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true" {...props}>
        {children}
      </svg>
    )
  }
}

